-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

create policy "questions follow listing visibility" on public.listing_questions
  as permissive
  for select
  to public
  using ((EXISTS ( SELECT 1
   FROM public.listings l
  WHERE l.id = listing_questions.listing_id AND ((l.status = ANY (ARRAY['active'::text, 'reserved'::text, 'sold'::text])) OR l.seller_id = (( SELECT auth.uid() AS uid))))));
